/// <summary>
/// Abstract base class for validity object
/// </summary>
abstract class NDX_ItemValidityObject
{
    date check_Date;
    ItemId check_ItemId;
    CustAccount check_CustAccount;
    smmChainId check_ChainId;

}

Method.Source:
public date parmCheck_Date(date _check_Date = check_Date)
{
    check_Date = _check_Date;
    return check_Date;
}

public ItemId parmCheck_ItemId(ItemId _check_ItemId = check_ItemId)
{
    check_ItemId = _check_ItemId;
    return check_ItemId;
}

public CustAccount parmCheck_CustAccount(CustAccount _check_CustAccount = check_CustAccount)
{
    check_CustAccount = _check_CustAccount;
    return check_CustAccount;
}

public smmChainId parmCheck_ChainId(smmChainId _check_ChainId = check_ChainId)
{
    check_ChainId = _check_ChainId;
    return check_ChainId;
}

